package com.tripmateai.controller; import com.tripmateai.dto.request.favorite.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.favorite.*; import com.tripmateai.enums.FavoriteTargetType; import com.tripmateai.service.FavoriteService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/favorites") @RequiredArgsConstructor public class FavoriteController {private final FavoriteService service; @PostMapping public ResponseEntity<ApiResponse<FavoriteResponse>> add(@Valid @RequestBody CreateFavoriteRequest r){return ResponseUtils.created(service.add(r),"Favorite added");} @GetMapping public ResponseEntity<ApiResponse<List<FavoriteResponse>>> list(@RequestParam(required=false) FavoriteTargetType targetType){return ResponseUtils.success(service.list(targetType),"Favorites retrieved");} @GetMapping("/check") public ResponseEntity<ApiResponse<Boolean>> check(@RequestParam FavoriteTargetType targetType,@RequestParam Long targetId){return ResponseUtils.success(service.check(targetType,targetId),"Favorite status retrieved");} @DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.delete(id);return ResponseUtils.success(null,"Favorite removed");}}
